  "unit_11": {
    "en": {
      "question": "Intermediate dialogue for Unit 11: Explain your routine, past experience, or plans in detail.",
      "hint": "Form a full complex sentence with connective phrases."
    },
    "ta": {
      "question": "பிரிவு 11 இடைநிலை உரையாடல்: உங்கள் வழக்கம் அல்லது திட்டங்களைப் பற்றி விரிவாகப் பேசுங்கள்.",
      "hint": "முழு வாக்கியங்களை அமைத்து உரையாடவும்."
    },
    "hi": {
      "question": "इकाई 11 मध्यवर्ती संवाद: अपनी दिनचर्या या योजनाओं का विस्तार से वर्णन करें।",
      "hint": "विस्तृत वाक्यों में उत्तर दें।"
    },
    "ml": {
      "question": "നിങ്ങളുടെ പ്ലാനുകളെക്കുറിച്ച് വിശദമായി സംസാരിക്കുക.",
      "hint": "പൂർണ്ണ വാക്യങ്ങൾ ഉപയോഗിക്കുക."
    },
    "te": {
      "question": "మీ ప్రణాళికలు లేదా అలవాట్లను వివరంగా తెలియజేయండి.",
      "hint": "పూర్తి వాక్యాలతో మాట్లాడండి."
    },
    "fr": {
      "question": "Dialogue intermédiaire (Unité 11) : Décrivez vos habitudes ou vos projets en détail.",
      "hint": "Formulez des phrases complètes et structurées."
    },
    "ja": {
      "question": "中級会話（ユニット11）：習慣や将来の予定について詳しく話してください。",
      "hint": "接続詞を使って文をつなげてみましょう。"
    },
    "ur": {
      "question": "اپنے معمولات یا منصوبوں کو تفصیل سے بیان کریں۔",
      "hint": "مکمل جملے بولیں۔"
    }
  },
